diagrams.source:
flowchart TB
  subgraph EC2G["EC2 インスタンス"]
    INS@{ svc: "Amazon EC2", label: "インスタンスプロファイル（ロールは 1 つだけ）" }
  end
  ROLE@{ svc: "AWS IAM", label: "✔ C: 既存のロールに SQS の権限を足す" }
  S3B@{ svc: "Amazon S3", label: "アプリのデータ" }
  SQS@{ svc: "Amazon SQS", label: "キュー" }
  INS --> ROLE
  ROLE -- "読み取り" --> S3B
  ROLE == "書き込み（追加）" ==> SQS
  INS -. "⚠ A: 1 つの上限は上げられない" .-> ROLE
  ROLE -. "⚠ B: 入れ替えると S3 を読めなくなる" .-> S3B
  INS -. "⚠ D: 長期のキーが増える" .-> SQS
